    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    original = [row[:] for row in grid]
    out = [row[:] for row in grid]

    def runs(side):
        if side in ("L", "R"):
            seq = [original[r][0 if side == "L" else w - 1] for r in range(h)]
        else:
            seq = original[0][:] if side == "T" else original[h - 1][:]
        result = []
        i = 0
        while i < len(seq):
            color = seq[i]
            if color == bg:
                i += 1
                continue
            j = i + 1
            while j < len(seq) and seq[j] == color:
                j += 1
            result.append((side, i, j, color))
            i = j
        return result

    pairs = []
    for a, b in (("L", "R"), ("T", "B")):
        for x in runs(a):
            for y in runs(b):
                if x[3] == y[3] and x[2] - x[1] == y[2] - y[1]:
                    pairs.append((x[2] - x[1], x, y))
    if not pairs:
        return out

    _, bar1, bar2 = max(pairs, key=lambda p: p[0])
    bars = [bar1, bar2]
    bar_color = bar1[3]
    length = bar1[2] - bar1[1]
    vertical_rays = bar1[0] in ("L", "R")

    # Points on a lane select that lane on both edge bars.
    lane_colors = {}
