        for c in range(w):
            val = original[r][c]
            if val == bg or val == bar_color:
                continue
            coord = r if vertical_rays else c
            for bar in bars:
                if bar[1] <= coord < bar[2]:
                    offset = coord - bar[1]
                    lane_colors.setdefault(offset, val)
                    break

    for offset, beam_color in lane_colors.items():
        for side, start, end, _ in bars:
            lane = start + offset
            if vertical_rays:
                if side == "L":
                    cells = [(lane, c) for c in range(1, w)]
                else:
                    cells = [(lane, c) for c in range(w - 2, -1, -1)]
            else:
                if side == "T":
                    cells = [(r, lane) for r in range(1, h)]
                else:
                    cells = [(r, lane) for r in range(h - 2, -1, -1)]

            for r, c in cells:
                val = original[r][c]
                if val != bg:
                    if val != bar_color:
                        out[r][c] = 4
                    break
                out[r][c] = beam_color

    return out
